cd /app && cat > stitch2.py <<'EOF'
import numpy as np, collections, sys
F=np.load('frames_text.npy',allow_pickle=True)
def clean(r):
    return r.replace('\x00','\x01').rstrip().rstrip('_').rstrip()
frames=[[clean(r) for r in f[1:]] for f in F]
def eq(a,b):
    if len(a)!=len(b): return False
    return all(x==y or x=='\x01' or y=='\x01' for x,y in zip(a,b))
def pref(a,b):
    if len(a)>len(b): return False
    return all(x==y or x=='\x01' or y=='\x01' for x,y in zip(a,b[:len(a)]))
doc=[];obs=[]
def put(idx,s):
    while len(obs)<=idx: obs.append([]);doc.append('')
    obs[idx].append(s)
    if len(s)>=len(doc[idx]): doc[idx]=s
log=[]
for i,lines in enumerate(frames):
    n=len(lines)
    if not doc:
        for k,l in enumerate(lines): put(k,l)
        log.append((i,0,n)); continue
    best=None
    for s in range(0,n+1):
        ov=n-s
        if ov>len(doc): continue
        ok=True
        for k in range(ov):
            d=doc[len(doc)-ov+k]; f=lines[k]
            if eq(d,f): continue
            if k==ov-1 and (pref(d,f) or pref(f,d)): continue
            ok=False;break
        if ok: best=s;break
    if best is None: best=n
    log.append((i,best,n-best))
    ov=n-best
    for k in range(ov): put(len(doc)-ov+k,lines[k])
    for k in range(ov,n): put(len(doc),lines[k])
print('doc',len(doc))
big=[l for l in log if l[1]>6]
print('big scrolls',len(big),big[:40])
final=[]
for ol in obs:
    m=max(len(s) for s in ol)
    c=collections.Counter([s for s in ol if len(s)==m])
    final.append(c.most_common(1)[0][0])
open('transcript.txt','w').write('\n'.join(final)+'\n')
cmds=[l[1:] for l in final if l.startswith('>')]
open('cmds.txt','w').write('\n'.join(cmds)+'\n')
print('cmds',len(cmds))
EOF
