def clean(s): return s.rstrip().rstrip('_').rstrip()
doc=[];obs=[];prev_k=0;used=0;skipped=[]
def put(i,s):
    while len(obs)<=i: obs.append([]); doc.append('')
    obs[i].append(s)
    if len(s)>len(doc[i]): doc[i]=s
gaps=[]
for fi in range(len(R)):
    if Q[fi].max()>=15: skipped.append(fi); continue
    rows=[clean(x) for x in (R[fi][1:] if S[fi] else R[fi])]
    n=len(rows)
    if not doc:
        for k,l in enumerate(rows): put(k,l)
        used+=1; continue
    chosen=None
    for k in range(prev_k, len(doc)+1):
        ov=min(n, len(doc)-k)
        ok=True; nb=0
        for i in range(ov):
            d=doc[k+i]; f=rows[i]
            if d==f:
                if d: nb+=1
                continue
            if k+i==len(doc)-1 and (d.startswith(f) or f.startswith(d)):
                nb+=1; continue
            ok=False; break
        if ok and (ov==0 or nb>=2 or len(doc)-k<=2):
            chosen=(k,ov); break
    if chosen is None: skipped.append(fi); continue
    k,ov=chosen
    if k>len(doc): gaps.append((fi,k,len(doc)))
    for i in range(ov): put(k+i,rows[i])
    for i in range(ov,n): put(len(doc),rows[i])
    prev_k=k; used+=1
print('used',used,'skipped',len(skipped),'gaps',gaps[:10],'doclines',len(doc))
final=[]
for ol in obs:
    m=max(len(s) for s in ol)
