import numpy as np, collections, sys
W='\x01'
R=np.load('rows.npy',allow_pickle=True); S=np.load('stat.npy'); Q=np.load('qual.npy')
def clean(s): return s.rstrip().rstrip('_').rstrip()
def meq(a,b):
    if len(a)!=len(b): return False
    return all(x==y or x==W or y==W for x,y in zip(a,b))
def mpref(a,b):
    if len(a)>len(b): return False
    return all(x==y or x==W or y==W for x,y in zip(a,b[:len(a)]))
doc=[];obs=[];prev_k=0;used=0;skip=[]
def put(i,s):
    while len(obs)<=i: obs.append([]); doc.append('')
    obs[i].append(s)
    if len(s)>len(doc[i]) or (len(s)==len(doc[i]) and doc[i].count(W)>s.count(W)): doc[i]=s
for fi in range(len(R)):
    rows=[clean(x) for x in (R[fi][1:] if S[fi] else R[fi])]
    if not any(rows): skip.append(fi); continue
    n=len(rows)
    if not doc:
        for k,l in enumerate(rows): put(k,l)
        used+=1; continue
    chosen=None
    for k in range(prev_k, len(doc)):
        ov=min(n, len(doc)-k); ok=True; nb=0
        for i in range(ov):
            d=doc[k+i]; f=rows[i]
            if meq(d,f):
                if d and W not in d and W not in f: nb+=1
                continue
            if k+i==len(doc)-1 and (mpref(d,f) or mpref(f,d)): continue
            ok=False; break
        if ok and (nb>=3 or len(doc)<=6): chosen=(k,ov); break
    if chosen is None: skip.append(fi); continue
    k,ov=chosen
    for i in range(ov): put(k+i,rows[i])
    for i in range(ov,n): put(len(doc),rows[i])
    prev_k=k; used+=1
runs=[];cur=[]
for i in skip:
    if cur and i==cur[-1]+1: cur.append(i)
    else:
        if cur: runs.append((cur[0],len(cur)))
        cur=[i]
if cur: runs.append((cur[0],len(cur)))
print('used',used,'skipped',len(skip),'doclines',len(doc))
print('skip runs>1:',[r for r in runs if r[1]>1][:40])
final=[]
for ol in obs:
    m=max(len(s) for s in ol)
    cands=[s for s in ol if len(s)==m]
    out=[]
    for pos in range(m):
        c=collections.Counter(s[pos] for s in cands if s[pos]!=W)
        out.append(c.most_common(1)[0][0] if c else W)
    final.append(''.join(out))
open('transcript.txt','w').write('\n'.join(final)+'\n')
cmds=[l[1:].strip() for l in final if l.startswith('>')]
open('cmds.txt','w').write('\n'.join(cmds)+'\n')
print('cmds',len(cmds))
print('wildcards left',sum(l.count(W) for l in final))
